effect.shader:
#define PI 3.14159265359
#define GOLDEN_ANGLE 2.3999632
mat2 rot2m(float a) {
float s = sin(a);
float c = cos(a);
return mat2(c, -s, s, c);
}
float irisMask(vec2 p, float sides, float curvature) {
float r = length(p);
if (r == 0.0) return 1.0;
float angle = atan(p.y, p.x);
float sector = 2.0 * PI / sides;
float a = mod(angle, sector) - 0.5 * sector;
float radiusEdge = cos(0.5 * sector) / cos(a);
float t = clamp(curvature * 0.5 + 0.5, 0.0, 1.0);
radiusEdge = mix(radiusEdge, 1.0, t);
float m = smoothstep(radiusEdge, radiusEdge - 0.02, r);
return m;
}
float focusFactor(vec2 uv) {
if (FOCUS_RADIUS <= 0.0) return 1.0;
vec2 focusPoint = vec2(FOCUS_X, FOCUS_Y);
float d = distance(uv, focusPoint);
float inner = FOCUS_RADIUS;
float outer = FOCUS_RADIUS + FOCUS_SOFTNESS;
outer = max(outer, inner + 0.001);
return smoothstep(inner, outer, d);
}
vec3 LensBokeh(sampler2D tex, vec2 uv, float radiusNorm) {
if (radiusNorm <= 0.0) {
return texture2DCv(tex, uv).rgb;
}
float iter = max(1.0, float(ITERATIONS));
vec2 vangle = vec2(0.0, radiusNorm / sqrt(iter));
vec3 acc = vec3(0.0);
vec3 div = vec3(0.0);
float r = 1.0;
float sides = max(3.0, IRIS_SIDES);
bool usePolygon = (IRIS_MODE == 1);
float irisRad = radians(IRIS_ROTATION);
mat2 irisRotM = rot2m(irisRad);
mat2 rot = rot2m(GOLDEN_ANGLE);
for (float j = 0.0; j < float(ITERATIONS); j++) {
r += 1.0 / r;
vangle = rot * vangle;
vec2 offset = (r - 1.0) * vangle;
vec2 pNorm = offset / radiusNorm;
pNorm *= vec2(SCALE_X, SCALE_Y);
pNorm = irisRotM * pNorm;
float mask = 1.0;
if (usePolygon) {
mask = irisMask(pNorm, sides, IRIS_CURVATURE);
}
if (mask <= 0.0) continue;
float dist = clamp(length(pNorm), 0.0, 1.0);
float shade = mix(1.0, 1.0 - dist, BOKEH_SHADING);
vec3 col = texture2DCv(tex, uv + offset).rgb;
vec3 w = pow(col, vec3(GAMMA));
acc += col * w * mask * shade;
div += w * mask * shade;
}
float divSum = div.x + div.y + div.z;
if (divSum <= 0.0) {
return texture2DCv(tex, uv).rgb;
}
return acc / div;
}
void main() {
vec2 uv = acScreenNorm;
vec4 texColor = texture2DCv(inputImg.texture, uv);
float baseRadiusNorm = RADIUS * progressa * 0.01;
float fFactor = focusFactor(uv);
float radiusNorm = baseRadiusNorm * fFactor;
vec3 blurRGB = LensBokeh(inputImg.texture, uv, radiusNorm);
vec4 blurColor = vec4(blurRGB, texColor.a);
vec4 factor = mix(texColor, blurColor, alpha);
vec4 resultfinal;
if (blendMode == 0) {
resultfinal = factor * bright;
resultfinal.a = texColor.a;
} else if (blendMode == 1) {
factor *= bright;
vec4 c = factor + vec4(1.0) * (1.0 - factor.a);
resultfinal = vec4((texColor.rgb / max(texColor.a, 1e-3)) * c.rgb, 1.0) * texColor.a;
} else if (blendMode == 2) {
factor *= bright;
vec3 src = texColor.rgb / max(texColor.a, 1e-3);
vec3 scr = 1.0 - ((1.0 - src) * (1.0 - factor.rgb));
resultfinal = vec4(scr, 1.0) * texColor.a;
}
gl_FragColor = resultfinal;
}
